 koeficienty:[{"typ_prevadzky": "skola_zakladna", "odpad_kod": "skolsky_kuchynsky_odpad", "koef_min": 45.0, "koef_stred": 55.0, "koef_max": 80.0, "koef_jednotka": "g na jedlo alebo lôžkodeň", "jedal_za_den": 1.0, "podiel_stravnikov": 0.75, "dni_rok": 190, "zdroj": "Malefors a kol. 2026, Environmental Development 57:101386 (45-47 g/stravník, Švédsko, 693 škôl); Zhang a kol. 2024, Front. Sustain. Food Syst. 8:1336220 (44,5 g/stravník, obed 55,3 g, Čína)", "doi": "10.1016/j.envdev.2025.101386; 10.3389/fsufs.2024.1336220", "uroven_dokazu": "B", "poznamka": "Dva nezávislé zdroje sa zhodujú na 45-55 g na porciu. Horná hranica 80 g pokrýva kuchynský odpad z prípravy, ktorý švédska metodika započítava len čiastočne. Podiel stravníkov 0,75 a 190 vyučovacích dní sú predpoklady riešiteľského tímu (úroveň D)."}, {"typ_prevadzky": "skola_materska", "odpad_kod": "skolsky_kuchynsky_odpad", "koef_min": 45.0, "koef_stred": 55.0, "koef_max": 80.0, "koef_jednotka": "g na jedlo alebo lôžkodeň", "jedal_za_den": 2.5, "podiel_stravnikov": 0.95, "dni_rok": 210, "zdroj": "Rovnaké koeficienty ako pri ZŠ; 2,5 jedla denne (desiata, obed, olovrant s nižšou hmotnosťou)", "doi": "10.1016/j.envdev.2025.101386", "uroven_dokazu": "C", "poznamka": "Prenos koeficientu zo školského na predškolské stravovanie je predpoklad, nie meranie."}, {"typ_prevadzky": "skola_stredna", "odpad_kod": "skolsky_kuchynsky_odpad", "koef_min": 45.0, "koef_stred": 55.0, "koef_max": 80.0, "koef_jednotka": "g na jedlo alebo lôžkodeň", "jedal_za_den": 1.0, "podiel_stravnikov": 0.5, "dni_rok": 190, "zdroj": "Malefors a kol. 2026 (starší žiaci 36 g odpadu z taniera vs. 18 g u mladších)", "doi": "10.1016/j.envdev.2025.101386", "uroven_dokazu": "B", "poznamka": "Nižší podiel stravníkov - stredoškoláci sa vo väčšej miere stravujú mimo školy."}, {"typ_prevadzky": "skolska_jedalen", "odpad_kod": "skolsky_kuchynsky_odpad", "koef_min": 45.0, "koef_stred": 55.0, "koef_max": 80.0, "koef_jednotka": "g na jedlo alebo lôžkodeň", "jedal_za_den": 1.0, "podiel_stravnikov": 1.0, "dni_rok": 190, "zdroj": "Malefors a kol. 2026; Zhang a kol. 2024", "doi": "10.1016/j.envdev.2025.101386; 10.3389/fsufs.2024.1336220", "uroven_dokazu": "B", "poznamka": "Kapacita jedálne je priamo počet stravníkov, preto podiel 1,0."}, {"typ_prevadzky": "nemocnica", "odpad_kod": "nemocnicny_kuchynsky_odpad", "koef_min": 240.0, "koef_stred": 320.0, "koef_max": 390.0, "koef_jednotka": "g na jedlo alebo lôžkodeň", "jedal_za_den": 1.0, "podiel_stravnikov": 0.659, "dni_rok": 365, "zdroj": "Abiad a kol. 2025, Front. Sustain. Food Syst. 9:1516331 (390 g/lôžko/deň, 16 nemocníc, Libanon); Burgoa Sánchez a de Camargo 2026, Sustainability 18(3):1458 (81 g/jedlo, Holandsko, ~240 g/deň); obložnosť akútnych lôžok 65,9 % - MF SR, Revízia výdavkov na nemocnice 2025", "doi": "10.3389/fsufs.2025.1516331; 10.3390/su18031458", "uroven_dokazu": "B", "poznamka": "Koeficient je na lôžkodeň, preto jedál_za_deň = 1. Obložnosť 65,9 % je nezávisle potvrdená výpočtom z NCZI (988 691 hospitalizácií × 7,8 dňa / 31 422 postelí / 365 = 67 %)."}],
